    for r, row in enumerate(grid):
        if row[-1] != bg:
            continue
        c = w - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0:
            continue
        color = row[c]
        start = c
        while start > 0 and row[start - 1] == color:
            start -= 1
        for j in range(c + 1, w):
            out[r][j] = 1
    return out
